#include "KS/SRC/widget_shared.h"

class bitmap_widget : public widget
{
};

class timer_widget : public widget
{
public:
  virtual void show();
  virtual void frame_advance( time_value_t time_inc );
  virtual void update_scale();
  virtual void render();
  virtual void set_layer( rhw_layer_e rhw_layer );

protected:
  bitmap_widget *digits[10];
  bitmap_widget *colon1, *colon2, *point, *bg;
  int minutes;
  int seconds1;
  int seconds2;
  int tenths;
  rational_t time_left;
  bool running, updated;
};

short MAGIC_OFFSET= 97;
short digit_y     = -23;
void timer_widget::render()
{
  const short digit_x[] = { -224-MAGIC_OFFSET, -66-MAGIC_OFFSET, 75-MAGIC_OFFSET, 224-MAGIC_OFFSET };

  bg->render();
  colon1->render();
  colon2->render();
  point->render();

  digits[minutes]->move_to( digit_x[0]*abs_S[0], digit_y );
  digits[minutes]->render();
  digits[seconds1]->move_to( digit_x[1]*abs_S[0], digit_y );
  digits[seconds1]->render();
  digits[seconds2]->move_to( digit_x[2]*abs_S[0], digit_y );
  digits[seconds2]->render();
  digits[tenths]->move_to( digit_x[3]*abs_S[0], digit_y );
  digits[tenths]->render();
}
